package vn.rtr.aeris.crew02;
import java.io.*;import java.net.*;import java.util.*;
public final class Frame02Test{
 static final class Fake extends Socket{long clock=0;int timeout=500,pos=0;final byte[]data;final int cost;final List<Integer>timeouts=new ArrayList<>();Fake(byte[]b,int cost){data=b;this.cost=cost;}public void setSoTimeout(int t){timeout=t;timeouts.add(t);}public InputStream getInputStream(){return new InputStream(){public int read()throws IOException{int delay=pos==0?0:cost;if(delay>timeout){clock+=timeout;throw new SocketTimeoutException();}clock+=delay;return pos<data.length?data[pos++]&255:-1;}public int read(byte[]b,int o,int n)throws IOException{int v=read();if(v<0)return -1;b[o]=(byte)v;return 1;}};}}
 public static void main(String[]args)throws Exception{Fake valid=new Fake(new byte[]{0,0,0,2,123,125},10);if(!Arrays.equals(FrameIO02.read(valid,()->valid.clock),new byte[]{123,125}))throw new AssertionError();Fake slow=new Fake(new byte[]{0,0,0,1,123},900);boolean refused=false;try{FrameIO02.read(slow,()->slow.clock);}catch(IOException e){refused=e.getMessage().equals("CREW_FRAME_DEADLINE");}if(!refused||slow.clock>3000||!slow.timeouts.contains(300))throw new AssertionError("absolute deadline "+slow.clock);for(byte[]b:new byte[][]{{0,0,0,0},{0,0,64,1},{0,0,0,2,123}}){Fake bad=new Fake(b,0);try{FrameIO02.read(bad,()->bad.clock);throw new AssertionError("accepted malformed");}catch(IOException expected){}}System.out.println("{\"status\":\"PASS\",\"outcomes\":5,\"scope\":\"ACTUAL_FRAMER_SCRIPTED_SOCKET_NO_NETWORK\",\"slowDripRefusedAtMs\":"+slow.clock+"}");}
}
